#ifndef APPLE_GPU_M4_WB_FIXTURE_H
#define APPLE_GPU_M4_WB_FIXTURE_H

#include "gpu-m4-store-fixture.h"

/* Fixed offline J713/25G83 W1 profile, NOT a firmware packet, UAPI, allocation
 * lease or hardware/cache witness. Generated by unchanged authorized Mesa
 * e6a74082 through linux-enablement-mac-alpha/tools/m4_gpu_wb_fixture/.
 * This distinct tooling format never broadens the r6 store parser.
 */
#define GPU_M4_WB_HEADER_SIZE 512U
#define GPU_M4_WB_BUNDLE_SIZE 50944U
#define GPU_M4_WB_RESOURCE_COUNT 6U
#define GPU_M4_WB_CHALLENGE_COUNT 2U
#define GPU_M4_WB_DESCRIPTOR_OFFSET 0xb0U
#define GPU_M4_WB_INPUT_VA 0x7101000000ULL
#define GPU_M4_WB_XOR 0x6d2b79f5U
#define GPU_M4_WB_PAGE_SIZE 0x4000U

enum gpu_m4_wb_resource_id {
	GPU_M4_WB_CONTAINER,
	GPU_M4_WB_PROGRAM,
	GPU_M4_WB_CDM,
	GPU_M4_WB_INPUT,
	GPU_M4_WB_OUTPUT,
	GPU_M4_WB_USC_WINDOW,
};

struct gpu_m4_wb_challenge {
	u32 input, expected_output, sentinel;
};

struct gpu_m4_wb_fixture {
	struct gpu_m4_store_resource resource[GPU_M4_WB_RESOURCE_COUNT];
	struct gpu_m4_wb_challenge challenge[GPU_M4_WB_CHALLENGE_COUNT];
	u64 usc_base, shader_entry, input_va, output_va, cdm_end;
	u32 main_size, nr_gprs, staging_halfs, compiler_d;
};

/* Independent cleanroom-generated r3 identities. Descriptor hashes alone do
 * not authenticate a self-consistent replacement. Runtime challenge selection
 * changes CPU initialization, never this firmware blob or executable bytes.
 */
static const u8 gpu_m4_wb_fixture_sha256[32] = {
	0x76, 0x05, 0xad, 0x51, 0x66, 0xd9, 0x63, 0xa0,
	0x11, 0xc6, 0xc1, 0xe2, 0xe0, 0x36, 0xda, 0xff,
	0x6a, 0xc5, 0x16, 0xcc, 0xf2, 0xc2, 0x70, 0x96,
	0xb6, 0x9a, 0x35, 0x2c, 0xb2, 0x75, 0x86, 0x92,
};
static const u8 gpu_m4_wb_compiler_sha256[32] = {
	0xff, 0xd7, 0x13, 0x64, 0x67, 0xfc, 0x3e, 0x4f,
	0xfb, 0xa2, 0xd1, 0xce, 0x48, 0x73, 0xaa, 0x96,
	0xa4, 0x3e, 0x79, 0xba, 0xd8, 0x99, 0x35, 0x88,
	0x48, 0xe8, 0x73, 0x3f, 0x13, 0xfd, 0x65, 0xec,
};

static inline bool gpu_m4_wb_canary(const u8 *data, u32 word, u32 seed)
{
	if (get_unaligned_le32(data) != word)
		return false;
	for (u32 i = 4; i < GPU_M4_WB_PAGE_SIZE; i++)
		if (data[i] != (u8)(seed + i * 17 + (i >> 8)))
			return false;
	return true;
}

/* Result unchanged on ANY failure. Success borrows immutable firmware bytes;
 * caller retains that actual firmware owner through all views/copies. No CPU
 * policy, native BO, private VA lease, root publication, engine work, reuse or
 * cache transition is granted here. Each challenge needs its own qualified
 * chronology/session; two records do not authorize a second submission.
 */
static inline int gpu_m4_wb_fixture_parse(const void *blob, size_t size,
	gpu_m4_store_hash hash, void *cookie, struct gpu_m4_wb_fixture *result)
{
	static const u8 magic[16] = "M4WB-FIXTURE";
	static const u64 resource_va[GPU_M4_WB_RESOURCE_COUNT] = {
		GPU_M4_STORE_CONTAINER_VA, GPU_M4_STORE_PROGRAM_VA,
		GPU_M4_STORE_CDM_VA, GPU_M4_WB_INPUT_VA,
		GPU_M4_STORE_OUTPUT_VA, GPU_M4_STORE_USC_BASE,
	};
	static const u32 resource_size[GPU_M4_WB_RESOURCE_COUNT] = {
		1088, 90, 48, GPU_M4_WB_PAGE_SIZE, GPU_M4_WB_PAGE_SIZE, GPU_M4_WB_PAGE_SIZE,
	};
	static const u32 metadata[16] = {
		GPU_M4_WB_XOR, 0, 0, 70, 70, 8, 1, 0, 0,
		1, 1, 1, 1, 1, 1, GPU_M4_WB_CHALLENGE_COUNT,
	};
	static const struct gpu_m4_wb_challenge challenge[GPU_M4_WB_CHALLENGE_COUNT] = {
		{ 0x13579bdf, 0x7e7ce22a, 0xdeadbeef },
		{ 0x2468ace1, 0x4943d514, 0x0badc0de },
	};
	struct gpu_m4_wb_fixture checked = { 0 };
	const u8 *data = blob;
	u8 digest[32];
	u32 cursor = GPU_M4_WB_HEADER_SIZE;
	int ret;

	if (!data || !hash || !result || size != GPU_M4_WB_BUNDLE_SIZE)
		return -EINVAL;
	if (memcmp(data, magic, sizeof(magic)) ||
	    get_unaligned_le32(data + 0x10) != 1 ||
	    get_unaligned_le32(data + 0x14) != GPU_M4_WB_HEADER_SIZE ||
	    get_unaligned_le32(data + 0x18) != size ||
	    get_unaligned_le32(data + 0x1c) != GPU_M4_WB_RESOURCE_COUNT ||
	    get_unaligned_le64(data + 0x20) != GPU_M4_STORE_USC_BASE ||
	    get_unaligned_le64(data + 0x28) != GPU_M4_STORE_ENTRY_VA ||
	    get_unaligned_le64(data + 0x30) != GPU_M4_WB_INPUT_VA ||
	    get_unaligned_le64(data + 0x38) != GPU_M4_STORE_OUTPUT_VA ||
	    get_unaligned_le64(data + 0x40) != GPU_M4_STORE_CDM_VA + 48 ||
	    !gpu_m4_store_zero(data + 0xa0, 0x10))
		return -EINVAL;
	for (u32 i = 0; i < 16; i++)
		if (get_unaligned_le32(data + 0x48 + i * 4) != metadata[i])
			return -EINVAL;
	for (u32 i = 0; i < GPU_M4_WB_CHALLENGE_COUNT; i++) {
		const u8 *record = data + 0x88 + i * 12;
		u32 input = get_unaligned_le32(record);
		u32 expected = input ^ GPU_M4_WB_XOR;

		if (input != challenge[i].input || expected != challenge[i].expected_output ||
		    get_unaligned_le32(record + 4) != expected ||
		    get_unaligned_le32(record + 8) != challenge[i].sentinel)
			return -EINVAL;
		checked.challenge[i] = challenge[i];
	}
	for (u32 i = 0; i < GPU_M4_WB_RESOURCE_COUNT; i++) {
		const u8 *descriptor = data + GPU_M4_WB_DESCRIPTOR_OFFSET + i * 56;
		u64 va = get_unaligned_le64(descriptor);
		u32 offset = get_unaligned_le32(descriptor + 8);
		u32 length = get_unaligned_le32(descriptor + 12);
		u32 aligned = (cursor + 63) & ~63U;

		if (va != resource_va[i] || length != resource_size[i] ||
		    get_unaligned_le32(descriptor + 48) != i + 1 ||
		    get_unaligned_le32(descriptor + 52) || offset != aligned ||
		    offset > size || length > size - offset ||
		    !gpu_m4_store_zero(data + cursor, offset - cursor))
			return -EINVAL;
		checked.resource[i] = (struct gpu_m4_store_resource) {
			.gpu_va = va, .data = data + offset, .size = length,
		};
		cursor = offset + length;
	}
	if (cursor != size ||
	    memcmp(checked.resource[GPU_M4_WB_USC_WINDOW].data,
		   checked.resource[GPU_M4_WB_CONTAINER].data, 0x340) ||
	    !gpu_m4_store_zero(checked.resource[GPU_M4_WB_USC_WINDOW].data + 0x340,
			       GPU_M4_WB_PAGE_SIZE - 0x340) ||
	    get_unaligned_le32(checked.resource[GPU_M4_WB_CONTAINER].data + 0x340) != 1088 - 0x340 ||
	    get_unaligned_le32(checked.resource[GPU_M4_WB_CDM].data + 40) != 0x60000160 ||
	    get_unaligned_le32(checked.resource[GPU_M4_WB_CDM].data + 44) != 0x40000000 ||
	    !gpu_m4_wb_canary(checked.resource[GPU_M4_WB_INPUT].data, challenge[0].input, 0xa3) ||
	    !gpu_m4_wb_canary(checked.resource[GPU_M4_WB_OUTPUT].data, challenge[0].sentinel, 0x5c))
		return -EINVAL;

	ret = hash(cookie, data, size, digest);
	if (ret)
		return ret < 0 ? ret : -EIO;
	if (memcmp(digest, gpu_m4_wb_fixture_sha256, sizeof(digest)))
		return -EBADMSG;
	for (u32 i = 0; i < GPU_M4_WB_RESOURCE_COUNT; i++) {
		ret = hash(cookie, checked.resource[i].data, checked.resource[i].size, digest);
		if (ret)
			return ret < 0 ? ret : -EIO;
		if (memcmp(digest, data + GPU_M4_WB_DESCRIPTOR_OFFSET + i * 56 + 16, sizeof(digest)))
			return -EBADMSG;
	}
	ret = hash(cookie, checked.resource[GPU_M4_WB_CONTAINER].data + 0x3c0, 70, digest);
	if (ret)
		return ret < 0 ? ret : -EIO;
	if (memcmp(digest, gpu_m4_wb_compiler_sha256, sizeof(digest)))
		return -EBADMSG;
	checked.usc_base = GPU_M4_STORE_USC_BASE;
	checked.shader_entry = GPU_M4_STORE_ENTRY_VA;
	checked.input_va = GPU_M4_WB_INPUT_VA;
	checked.output_va = GPU_M4_STORE_OUTPUT_VA;
	checked.cdm_end = GPU_M4_STORE_CDM_VA + 48;
	checked.main_size = 70;
	checked.nr_gprs = 8;
	*result = checked;
	return 0;
}

#endif
